// Tokenizzazione sicura del messaggio Telegram
const raw = typeof msg.payload?.content === "string" ? msg.payload.content : "";
const tokens = raw.toLowerCase().match(/[a-z0-9]+/g) || [];

// 1) Città
let city = null;
if (tokens.includes("milan") || tokens.includes("milano")) {
    city = "Milano";
} else if (tokens.includes("rome") || tokens.includes("roma")) {
    city = "Rome";
}

// 2) Tipo di query (controlliamo "wind" prima di "forecast")
let queryType = null;
if (tokens.includes("wind")) {
    queryType = "wind";
} else if (tokens.includes("weather") || tokens.includes("forecast")) {
    queryType = "weather";
}

// 3) Giorni (1 = tomorrow, 2 = in two days)
let days = -1;
if (tokens.includes("tomorrow") || tokens.includes("one") || tokens.includes("1")) {
    days = 1;
} else if (tokens.includes("two") || tokens.includes("2")) {
    days = 2;
}

if (city === null || queryType === null || days === -1) {
    return [null, null, msg];
}

msg.city = city;
msg.queryType = queryType;
msg.days = days;

if (city === "Milano") {
    return [msg, null, null];
}
return [null, msg, null];

const list = Array.isArray(msg.payload) ? msg.payload : [];
if (list.length === 0) {
    msg.payload = { reply: "Sorry, weather forecast data is currently unavailable." };
    return msg;
}

// Seleziona lo slot delle 12:00 UTC del giorno target (oggi + msg.days)
