    list.find(item => item.dt_txt === `${targetDateStr} 12:00:00`) ||
    list.find(item => item.dt_txt && item.dt_txt.startsWith(targetDateStr)) ||
    list[Math.min(msg.days * 8 - 1, list.length - 1)];

